param([string]$Directory='app/docs/review-20261101',[string]$ResultsDirectory='app/artifacts/final-system-test')
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.IO.Compression.FileSystem
$Directory=[IO.Path]::GetFullPath($Directory);$ResultsDirectory=[IO.Path]::GetFullPath($ResultsDirectory)
$results=Get-Content -LiteralPath (Join-Path $ResultsDirectory 'documented-results.json') -Raw -Encoding UTF8|ConvertFrom-Json
$model=Get-Content -LiteralPath (Join-Path $Directory 'spec-test-model.json') -Raw -Encoding UTF8|ConvertFrom-Json
$byId=@{};foreach($r in $results){if($byId.ContainsKey($r.id)){throw ('Repeated result without explicit retry record '+$r.id)};$byId[$r.id]=$r}
$source=Join-Path $Directory 'DacTa_Kem_TestCase_20261101.docx';$output=Join-Path $Directory 'DacTa_TestCase_KetQua_20261101.docx';$W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
function SetText($cell,[string]$value,$ns){$ts=@($cell.SelectNodes('.//w:t',$ns));if(-not $ts.Count){throw 'No text run in result cell'};$ts[0].InnerText=$value;for($i=1;$i-lt $ts.Count;$i++){$ts[$i].InnerText=''}}
$a=[IO.Compression.ZipFile]::OpenRead($source)
try{$s=[IO.StreamReader]::new($a.GetEntry('word/document.xml').Open());$d=[Xml.XmlDocument]::new();$d.PreserveWhitespace=$true;$d.LoadXml($s.ReadToEnd());$s.Dispose();$ns=[Xml.XmlNamespaceManager]::new($d.NameTable);$ns.AddNamespace('w',$W);$tables=@($d.SelectNodes('//w:body/w:tbl',$ns));if($tables.Count-ne 108){throw 'Wrong source table count'};$pass=0;$fail=0;$pending=0;$seen=@{};$rowsOut=@()
for($i=0;$i-lt $model.tables.Count;$i++){$tc=$tables[$i*2+1];$rows=@($tc.SelectNodes('w:tr',$ns));foreach($row in $rows|Select-Object -Skip 1){$cells=@($row.SelectNodes('w:tc',$ns));$id=($cells[0].SelectNodes('.//w:t',$ns)|ForEach-Object{$_.InnerText})-join '';$r=$byId[$id];if($r){if($r.status-notin @('Pass','Fail')){throw 'Unsupported result status'};SetText $cells[6] ($r.actual+' Bằng chứng: '+$r.evidence+'; lúc '+([DateTimeOffset]::Parse($r.started_at).ToOffset([TimeSpan]::FromHours(7)).ToString('HH:mm - dd/MM/yyyy'))) $ns;SetText $cells[7] $r.status $ns;$seen[$id]=$true;if($r.status-eq 'Pass'){$pass++}else{$fail++};if($r.amendment){foreach($pair in @(@('pre',2),@('description',3),@('data',4),@('expected',5))){if($r.amendment.($pair[0])){SetText $cells[$pair[1]] $r.amendment.($pair[0]) $ns}}};$rowsOut+=@{id=$id;status=$r.status;actual=$r.actual;evidence=$r.evidence;started_at=$r.started_at}}
else{SetText $cells[6] 'Chưa thực thi theo mã TC; không suy Pass từ kết quả nhóm.' $ns;SetText $cells[7] 'Chưa chạy' $ns;$pending++;$rowsOut+=@{id=$id;status='Chưa chạy';actual='Chưa có bằng chứng riêng theo mã.'}}}}
if($seen.Count-ne $results.Count){throw 'Result IDs missing from Word'};if($pass+$fail+$pending-ne $model.cases.Count){throw 'Total mismatch'}
$summary='Kết quả thực thi theo mã TC: '+$pass+' Pass, '+$fail+' Fail, '+$pending+' Chưa chạy / '+$model.cases.Count+' ca. Chỉ Pass khi có kiểm chứng thực tế; không đồng nhất kết quả nhóm với kết quả từng ca. Chi tiết và request ID ở app/artifacts/final-system-test. T là ngày chạy theo UTC+7; dữ liệu thử nằm ở Docker riêng cổng 3310.'
foreach($p in $d.SelectNodes('//w:body/w:p',$ns)){$text=($p.SelectNodes('.//w:t',$ns)|ForEach-Object{$_.InnerText})-join '';if($text.StartsWith('Hướng dẫn kiểm thử:')){SetText $p $summary $ns;break}}
if(Test-Path -LiteralPath $output){if([IO.Path]::GetDirectoryName($output)-ne $Directory-or $output-eq $source){throw 'Unsafe output'};[IO.File]::Delete($output)}
$z=[IO.Compression.ZipFile]::Open($output,[IO.Compression.ZipArchiveMode]::Create);try{foreach($part in $a.Entries){$target=$z.CreateEntry($part.FullName,[IO.Compression.CompressionLevel]::Optimal);$stream=$target.Open();try{if($part.FullName-eq 'word/document.xml'){$bytes=[Text.UTF8Encoding]::new($false).GetBytes($d.OuterXml);$stream.Write($bytes,0,$bytes.Length)}else{$inputStream=$part.Open();try{$inputStream.CopyTo($stream)}finally{$inputStream.Dispose()}}}finally{$stream.Dispose()}}}finally{$z.Dispose()}
@{total=$model.cases.Count;pass=$pass;fail=$fail;notRun=$pending;matchedEvidence=$seen.Count;sourceUntouched=$true;output=[IO.Path]::GetFileName($output);sha256=(Get-FileHash -LiteralPath $output -Algorithm SHA256).Hash}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $Directory 'EXECUTED_TESTCASE_PROOF.json') -Encoding UTF8
$rowsOut|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $Directory 'KET_QUA_THEO_MA_TC.json') -Encoding UTF8
Write-Output $summary
}finally{$a.Dispose()}
